:root {
  --bg-deep: #0a0a12;
  --bg-panel: #12121f;
  --neon-cyan: #00f5ff;
  --neon-magenta: #ff00aa;
  --neon-lime: #39ff14;
  --neon-orange: #ff6b00;
  --text-dim: #8899aa;
  --text-bright: #e8f4ff;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg-deep);
  color: var(--text-bright);
  font-family: "Segoe UI", system-ui, sans-serif;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1rem;
}

#app {
  max-width: 960px;
  width: 100%;
}

header {
  text-align: center;
  margin-bottom: 1rem;
}

header h1 {
  font-size: 2rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--neon-cyan);
  text-shadow: 0 0 10px var(--neon-cyan), 0 0 30px rgba(0, 245, 255, 0.4);
}

#hud {
  display: flex;
  justify-content: center;
  gap: 2rem;
  margin-top: 0.5rem;
  font-size: 1rem;
}

#score {
  color: var(--neon-lime);
  font-weight: bold;
}

#status {
  color: var(--neon-magenta);
}

main {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
  justify-content: center;
  align-items: flex-start;
}

#game-canvas {
  display: block;
  background: var(--bg-panel);
  border: 2px solid var(--neon-cyan);
  box-shadow: 0 0 15px rgba(0, 245, 255, 0.3), inset 0 0 40px rgba(0, 0, 0, 0.5);
  border-radius: 4px;
  outline: none;
  cursor: crosshair;
}

#game-canvas:focus {
  box-shadow: 0 0 20px rgba(0, 245, 255, 0.6), inset 0 0 40px rgba(0, 0, 0, 0.5);
}

#controls-panel {
  background: var(--bg-panel);
  border: 1px solid rgba(0, 245, 255, 0.25);
  border-radius: 4px;
  padding: 1rem 1.25rem;
  min-width: 220px;
}

#controls-panel h2 {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--neon-magenta);
  margin-bottom: 0.75rem;
}

#controls-panel ul {
  list-style: none;
  font-size: 0.9rem;
  line-height: 1.8;
  color: var(--text-dim);
}

kbd {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 3px;
  padding: 0.1em 0.4em;
  font-family: monospace;
  font-size: 0.85em;
  color: var(--text-bright);
}

footer {
  text-align: center;
  margin-top: 1rem;
}

#message {
  color: var(--neon-orange);
  font-size: 0.95rem;
  min-height: 1.4em;
}

/** Entity definitions and helpers for Neon Serpents */

export const GRID_COLS = 32;
export const GRID_ROWS = 24;
export const TICK_MS = 120;

export const DIRECTION = {
  UP: { x: 0, y: -1 },
  DOWN: { x: 0, y: 1 },
  LEFT: { x: -1, y: 0 },
  RIGHT: { x: 1, y: 0 },
};

export const OPPOSITE = {
  UP: 'DOWN',
  DOWN: 'UP',
  LEFT: 'RIGHT',
  RIGHT: 'LEFT',
};

export const NEON_COLORS = [
  '#00f5ff',
  '#ff00aa',
  '#39ff14',
  '#ff6b00',
  '#bf00ff',
  '#ffff00',
];

export const GAME_STATE = {
  IDLE: 'idle',
  RUNNING: 'running',
  PAUSED: 'paused',
  OVER: 'over',
};

let nextEntityId = 1;

export function createId() {
  return nextEntityId++;
}

export function resetEntityIds() {
  nextEntityId = 1;
}

export function dirKey(dir) {
  for (const [key, val] of Object.entries(DIRECTION)) {
    if (val.x === dir.x && val.y === dir.y) {
      return key;
    }
  }
  return 'RIGHT';
}

export function wrapCoord(value, max) {
  if (value < 0) {
    return max - 1;
  }
  if (value >= max) {
    return 0;
  }
  return value;
}

export class Snake {
  constructor(options) {
    this.id = options.id ?? createId();
    this.name = options.name ?? 'Snake';
    this.color = options.color ?? NEON_COLORS[0];
    this.isPlayer = options.isPlayer ?? false;
    this.isBot = options.isBot ?? false;
    this.alive = true;
    this.score = 0;
    this.growPending = 0;
    this.direction = { ...(options.direction || DIRECTION.RIGHT) };
    this.nextDirection = { ...this.direction };
    this.segments = options.segments.map((s) => ({ x: s.x, y: s.y }));
  }

  head() {
    return this.segments[0];
  }

  setDirection(dir) {
    const currentKey = dirKey(this.direction);
    const newKey = dirKey(dir);
    if (OPPOSITE[currentKey] === newKey) {
      return;
    }
    this.nextDirection = { ...dir };
  }

  applyBufferedDirection() {
    const currentKey = dirKey(this.direction);
    const newKey = dirKey(this.nextDirection);
    if (OPPOSITE[currentKey] !== newKey) {
      this.direction = { ...this.nextDirection };
    }
  }

  move(wrapWalls) {
    if (!this.alive) {
      return;
    }
    this.applyBufferedDirection();
    const head = this.head();
    let nx = head.x + this.direction.x;
    let ny = head.y + this.direction.y;

    if (wrapWalls) {
      nx = wrapCoord(nx, GRID_COLS);
      ny = wrapCoord(ny, GRID_ROWS);
    }

    this.segments.unshift({ x: nx, y: ny });
    if (this.growPending > 0) {
      this.growPending -= 1;
    } else {
      this.segments.pop();
    }
  }

  grow(amount = 1) {
    this.growPending += amount;
    this.score += amount;
  }

  occupies(x, y) {
    return this.segments.some((s) => s.x === x && s.y === y);
  }

  hitsSelf() {
    const head = this.head();
    const body = this.segments.slice(1);
    return body.some((s) => s.x === head.x && s.y === head.y);
  }
}

export class Food {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.pulse = 0;
  }

  tick() {
    this.pulse = (this.pulse + 0.15) % (Math.PI * 2);
  }
}

export function randomEmptyCell(occupancyFn) {
  const free = [];
  for (let y = 0; y < GRID_ROWS; y++) {
    for (let x = 0; x < GRID_COLS; x++) {
      if (!occupancyFn(x, y)) {
        free.push({ x, y });
      }
    }
  }
  if (free.length === 0) {
    return null;
  }
  return free[Math.floor(Math.random() * free.length)];
}

export function createPlayerSnake() {
  const cx = Math.floor(GRID_COLS / 4);
  const cy = Math.floor(GRID_ROWS / 2);
  return new Snake({
    name: 'You',
    color: NEON_COLORS[0],
    isPlayer: true,
    direction: DIRECTION.RIGHT,
    segments: [
      { x: cx, y: cy },
      { x: cx - 1, y: cy },
      { x: cx - 2, y: cy },
    ],
  });
}

export function createBotSnake(index) {
  const positions = [
    { x: Math.floor((GRID_COLS * 3) / 4), y: Math.floor(GRID_ROWS / 4), dir: DIRECTION.LEFT },
    { x: Math.floor(GRID_COLS / 2), y: Math.floor((GRID_ROWS * 3) / 4), dir: DIRECTION.UP },
    { x: Math.floor(GRID_COLS / 4), y: Math.floor((GRID_ROWS * 3) / 4), dir: DIRECTION.RIGHT },
  ];
  const pos = positions[index % positions.length];
  const segs = [
    { x: pos.x, y: pos.y },
    { x: pos.x - pos.dir.x, y: pos.y - pos.dir.y },
    { x: pos.x - pos.dir.x * 2, y: pos.y - pos.dir.y * 2 },
  ];
  return new Snake({
    name: 'Bot ' + (index + 1),
    color: NEON_COLORS[(index + 1) % NEON_COLORS.length],
    isBot: true,
    direction: { ...pos.dir },
    segments: segs,
  });
}

/** Canvas rendering for Neon Serpents */

import { GRID_COLS, GRID_ROWS, GAME_STATE } from './entities.js';

export class Renderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.cellW = canvas.width / GRID_COLS;
    this.cellH = canvas.height / GRID_ROWS;
  }

  clear() {
    const ctx = this.ctx;
    const canvas = this.canvas;
    ctx.fillStyle = '#12121f';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    this.drawGrid();
  }

  drawGrid() {
    const ctx = this.ctx;
    const canvas = this.canvas;
    const cellW = this.cellW;
    const cellH = this.cellH;
    ctx.strokeStyle = 'rgba(0, 245, 255, 0.08)';
    ctx.lineWidth = 1;
    for (let x = 0; x <= GRID_COLS; x++) {
      ctx.beginPath();
      ctx.moveTo(x * cellW, 0);
      ctx.lineTo(x * cellW, canvas.height);
      ctx.stroke();
    }
    for (let y = 0; y <= GRID_ROWS; y++) {
      ctx.beginPath();
      ctx.moveTo(0, y * cellH);
      ctx.lineTo(canvas.width, y * cellH);
      ctx.stroke();
    }
  }

  drawFood(food) {
    if (!food) {
      return;
    }
    const ctx = this.ctx;
    const cellW = this.cellW;
    const cellH = this.cellH;
    const cx = food.x * cellW + cellW / 2;
    const cy = food.y * cellH + cellH / 2;
    const pulse = 0.6 + Math.sin(food.pulse) * 0.2;
    const radius = Math.min(cellW, cellH) * 0.35 * pulse;

    ctx.save();
    ctx.shadowColor = '#ff6b00';
    ctx.shadowBlur = 12;
    ctx.fillStyle = '#ff6b00';
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#ffe066';
    ctx.beginPath();
    ctx.arc(cx, cy, radius * 0.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  drawSnake(snake) {
    if (!snake.segments.length) {
      return;
    }
    const ctx = this.ctx;
    const cellW = this.cellW;
    const cellH = this.cellH;
    const pad = 2;

    snake.segments.forEach((seg, i) => {
      const x = seg.x * cellW + pad;
      const y = seg.y * cellH + pad;
      const w = cellW - pad * 2;
      const h = cellH - pad * 2;
      const alpha = snake.alive ? 1 : 0.35;

      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.shadowColor = snake.color;
      ctx.shadowBlur = i === 0 ? 14 : 8;
      ctx.fillStyle = snake.color;
      const radius = i === 0 ? 4 : 3;
      this.roundRect(x, y, w, h, radius);
      ctx.fill();

      if (i === 0) {
        ctx.fillStyle = '#ffffff';
        ctx.globalAlpha = alpha * 0.9;
        const eyeR = Math.min(w, h) * 0.12;
        ctx.beginPath();
        ctx.arc(x + w * 0.65, y + h * 0.35, eyeR, 0, Math.PI * 2);
        ctx.arc(x + w * 0.65, y + h * 0.65, eyeR, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    });

    if (snake.name) {
      const head = snake.segments[0];
      ctx.save();
      ctx.font = '10px monospace';
      ctx.fillStyle = snake.alive ? snake.color : '#666666';
      ctx.textAlign = 'center';
      ctx.fillText(snake.name, head.x * cellW + cellW / 2, head.y * cellH - 4);
      ctx.restore();
    }
  }

  roundRect(x, y, w, h, r) {
    const ctx = this.ctx;
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  drawOverlay(state, playerScore, winnerText) {
    const canvas = this.canvas;
    if (state === GAME_STATE.IDLE) {
      this.drawCenterText('NEON SERPENTS', '#00f5ff', 28);
      this.drawCenterText('Press Space or Enter to Start', '#8899aa', 14, canvas.height / 2 + 36);
      return;
    }
    if (state === GAME_STATE.PAUSED) {
      const ctx = this.ctx;
      ctx.fillStyle = 'rgba(0, 0, 0, 0.55)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      this.drawCenterText('PAUSED', '#ff00aa', 32);
      this.drawCenterText('Press P to Resume', '#8899aa', 14, canvas.height / 2 + 32);
      return;
    }
    if (state === GAME_STATE.OVER) {
      const ctx = this.ctx;
      ctx.fillStyle = 'rgba(0, 0, 0, 0.65)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      this.drawCenterText('GAME OVER', '#ff0066', 32);
      const msg = winnerText || ('Score: ' + playerScore);
      this.drawCenterText(msg, '#39ff14', 16, canvas.height / 2 + 28);
      this.drawCenterText('Press Space or Enter to Restart', '#8899aa', 13, canvas.height / 2 + 56);
    }
  }

  drawCenterText(text, color, size, yOffset) {
    const ctx = this.ctx;
    const canvas = this.canvas;
    const y = yOffset !== undefined ? yOffset : canvas.height / 2;
    ctx.save();
    ctx.font = 'bold ' + size + 'px "Segoe UI", system-ui, sans-serif';
    ctx.fillStyle = color;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = color;
    ctx.shadowBlur = 12;
    ctx.fillText(text, canvas.width / 2, y);
    ctx.restore();
  }

  renderFrame(game) {
    this.clear();
    game.foods.forEach((f) => this.drawFood(f));
    game.snakes.forEach((s) => this.drawSnake(s));
    this.drawOverlay(game.state, game.playerScore(), game.winnerText);
  }
}

/** Entry point for Neon Serpents */

import { Game } from './game.js';
import { Renderer } from './render.js';
import { DIRECTION, GAME_STATE, TICK_MS } from './entities.js';

const canvas = document.getElementById('game-canvas');
const scoreEl = document.getElementById('score');
const statusEl = document.getElementById('status');
const messageEl = document.getElementById('message');

const game = new Game();
const renderer = new Renderer(canvas);

let lastTime = 0;
let accumulator = 0;

const KEY_TO_DIRECTION = {
  ArrowUp: DIRECTION.UP,
  ArrowDown: DIRECTION.DOWN,
  ArrowLeft: DIRECTION.LEFT,
  ArrowRight: DIRECTION.RIGHT,
  w: DIRECTION.UP,
  W: DIRECTION.UP,
  s: DIRECTION.DOWN,
  S: DIRECTION.DOWN,
  a: DIRECTION.LEFT,
  A: DIRECTION.LEFT,
  d: DIRECTION.RIGHT,
  D: DIRECTION.RIGHT,
};

function updateHud() {
  scoreEl.textContent = String(game.playerScore());

  switch (game.state) {
    case GAME_STATE.RUNNING:
      statusEl.textContent = 'Playing';
      break;
    case GAME_STATE.PAUSED:
      statusEl.textContent = 'Paused';
      break;
    case GAME_STATE.OVER:
      statusEl.textContent = 'Game Over';
      break;
    default:
      statusEl.textContent = 'Ready';
      break;
  }
}

function updateMessage() {
  switch (game.state) {
    case GAME_STATE.IDLE:
      messageEl.textContent = 'Press Space or Enter to start.';
      break;
    case GAME_STATE.RUNNING:
      messageEl.textContent = 'Collect neon orbs. Avoid snakes and yourself.';
      break;
    case GAME_STATE.PAUSED:
      messageEl.textContent = 'Paused — press P to resume.';
      break;
    case GAME_STATE.OVER:
      messageEl.textContent = game.winnerText || 'Press Space or Enter to restart.';
      break;
    default:
      break;
  }
}

function setPlayerDirection(dir) {
  const player = game.playerSnake();
  if (player && player.alive && game.state === GAME_STATE.RUNNING) {
    player.setDirection(dir);
  }
}

function handleStartOrRestart() {
  if (game.state === GAME_STATE.IDLE || game.state === GAME_STATE.OVER) {
    game.start();
    updateHud();
    updateMessage();
  }
}

function handlePauseToggle() {
  if (game.state === GAME_STATE.RUNNING || game.state === GAME_STATE.PAUSED) {
    game.togglePause();
    updateHud();
    updateMessage();
  }
}

function onKeyDown(event) {
  const dir = KEY_TO_DIRECTION[event.key];
  if (dir) {
    event.preventDefault();
    setPlayerDirection(dir);
    return;
  }

  if (event.key === ' ' || event.key === 'Enter') {
    event.preventDefault();
    handleStartOrRestart();
    return;
  }

  if (event.key === 'p' || event.key === 'P') {
    event.preventDefault();
    handlePauseToggle();
  }
}

function frame(time) {
  if (!lastTime) {
    lastTime = time;
  }

  const delta = time - lastTime;
  lastTime = time;
  accumulator += delta;

  while (accumulator >= TICK_MS) {
    game.tick();
    accumulator -= TICK_MS;
  }

  updateHud();
  if (game.state === GAME_STATE.RUNNING || game.state === GAME_STATE.OVER) {
    updateMessage();
  }

  renderer.renderFrame(game);
  requestAnimationFrame(frame);
}

window.addEventListener('keydown', onKeyDown);
canvas.addEventListener('click', () => canvas.focus());

updateHud();
updateMessage();
renderer.renderFrame(game);
canvas.focus();
requestAnimationFrame(frame);

/** Core game logic for Neon Serpents */

import {
  GAME_STATE,
  Food,
  randomEmptyCell,
  createPlayerSnake,
  createBotSnake,
  resetEntityIds,
} from './entities.js';
import { updateBots } from './bots.js';

export const BOT_COUNT = 2;
export const FOOD_COUNT = 3;
export const WRAP_WALLS = true;

export class Game {
  constructor() {
    this.state = GAME_STATE.IDLE;
    this.snakes = [];
    this.foods = [];
    this.winnerText = null;
  }

  playerSnake() {
    return this.snakes.find((s) => s.isPlayer) || null;
  }

  playerScore() {
    const player = this.playerSnake();
    return player ? player.score : 0;
  }

  isOccupied(x, y) {
    for (const food of this.foods) {
      if (food.x === x && food.y === y) {
        return true;
      }
    }
    for (const snake of this.snakes) {
      if (snake.occupies(x, y)) {
        return true;
      }
    }
    return false;
  }

  spawnFood() {
    const cell = randomEmptyCell((x, y) => this.isOccupied(x, y));
    if (cell) {
      this.foods.push(new Food(cell.x, cell.y));
    }
  }

  startNewRound() {
    resetEntityIds();
    this.snakes = [createPlayerSnake()];
    for (let i = 0; i < BOT_COUNT; i += 1) {
      this.snakes.push(createBotSnake(i));
    }
    this.foods = [];
    for (let i = 0; i < FOOD_COUNT; i += 1) {
      this.spawnFood();
    }
    this.winnerText = null;
    this.state = GAME_STATE.RUNNING;
  }

  start() {
    this.startNewRound();
  }

  togglePause() {
    if (this.state === GAME_STATE.RUNNING) {
      this.state = GAME_STATE.PAUSED;
      return;
    }
    if (this.state === GAME_STATE.PAUSED) {
      this.state = GAME_STATE.RUNNING;
    }
  }

  tick() {
    if (this.state !== GAME_STATE.RUNNING) {
      return;
    }

    updateBots(this, WRAP_WALLS);

    for (const snake of this.snakes) {
      if (snake.alive) {
        snake.move(WRAP_WALLS);
      }
    }

    this.resolveCollisions();
    this.collectFood();
    this.foods.forEach((food) => food.tick());

    const player = this.playerSnake();
    if (!player || !player.alive) {
      this.state = GAME_STATE.OVER;
      this.winnerText = this.buildResultMessage();
    }
  }

  resolveCollisions() {
    for (const snake of this.snakes) {
      if (snake.alive && snake.hitsSelf()) {
        snake.alive = false;
      }
    }

    const headGroups = new Map();
    for (const snake of this.snakes) {
      if (!snake.alive) {
        continue;
      }
      const head = snake.head();
      const key = head.x + ',' + head.y;
      if (!headGroups.has(key)) {
        headGroups.set(key, []);
      }
      headGroups.get(key).push(snake);
    }

    for (const group of headGroups.values()) {
      if (group.length <= 1) {
        continue;
      }
      const maxLen = Math.max(...group.map((s) => s.segments.length));
      const tiedLeaders = group.filter((s) => s.segments.length === maxLen);
      if (tiedLeaders.length > 1) {
        group.forEach((s) => {
          s.alive = false;
        });
      } else {
        group.forEach((s) => {
          if (s.segments.length < maxLen) {
            s.alive = false;
          }
        });
      }
    }

    for (const snake of this.snakes) {
      if (!snake.alive) {
        continue;
      }
      const head = snake.head();
      for (const other of this.snakes) {
        if (other.id === snake.id || !other.alive) {
          continue;
        }
        for (let i = 1; i < other.segments.length; i += 1) {
          const seg = other.segments[i];
          if (seg.x === head.x && seg.y === head.y) {
            snake.alive = false;
            break;
          }
        }
      }
    }
  }

  collectFood() {
    for (const snake of this.snakes) {
      if (!snake.alive) {
        continue;
      }
      const head = snake.head();
      for (let i = this.foods.length - 1; i >= 0; i -= 1) {
        const food = this.foods[i];
        if (food.x === head.x && food.y === head.y) {
          snake.grow();
          this.foods.splice(i, 1);
          this.spawnFood();
        }
      }
    }
  }

  buildResultMessage() {
    const player = this.playerSnake();
    const playerScore = player ? player.score : 0;

    if (player && player.alive) {
      return 'You survived! Score: ' + playerScore;
    }

    const sorted = [...this.snakes].sort((a, b) => b.score - a.score);
    const leader = sorted[0];

    if (leader && leader.isPlayer) {
      return 'Top score: ' + playerScore;
    }

    if (leader) {
      return leader.name + ' wins. Your score: ' + playerScore;
    }

    return 'Score: ' + playerScore;
  }
}

/** Bot AI for Neon Serpents */

import { DIRECTION, GRID_COLS, GRID_ROWS, wrapCoord } from './entities.js';

const DIRECTIONS = [DIRECTION.UP, DIRECTION.DOWN, DIRECTION.LEFT, DIRECTION.RIGHT];

function wrapDelta(from, to, max) {
  let delta = to - from;
  const half = max / 2;
  if (delta > half) {
    delta -= max;
  }
  if (delta < -half) {
    delta += max;
  }
  return delta;
}

function manhattanWrapped(ax, ay, bx, by) {
  const dx = Math.abs(wrapDelta(ax, bx, GRID_COLS));
  const dy = Math.abs(wrapDelta(ay, by, GRID_ROWS));
  return dx + dy;
}

function nearestFood(head, foods) {
  if (!foods.length) {
    return null;
  }

  let best = null;
  let bestDist = Infinity;

  for (const food of foods) {
    const dist = manhattanWrapped(head.x, head.y, food.x, food.y);
    if (dist < bestDist) {
      bestDist = dist;
      best = food;
    }
  }

  return best;
}

function directionToward(head, target) {
  const dx = wrapDelta(head.x, target.x, GRID_COLS);
  const dy = wrapDelta(head.y, target.y, GRID_ROWS);

  if (Math.abs(dx) > Math.abs(dy)) {
    return dx > 0 ? DIRECTION.RIGHT : DIRECTION.LEFT;
  }

  if (Math.abs(dy) > 0) {
    return dy > 0 ? DIRECTION.DOWN : DIRECTION.UP;
  }

  return null;
}

function nextCell(head, dir, wrapWalls) {
  let nx = head.x + dir.x;
  let ny = head.y + dir.y;

  if (wrapWalls) {
    nx = wrapCoord(nx, GRID_COLS);
    ny = wrapCoord(ny, GRID_ROWS);
  }

  return { x: nx, y: ny };
}

function isOccupiedBySnake(game, x, y, selfId) {
  for (const snake of game.snakes) {
    if (!snake.alive) {
      continue;
    }

    const isSelf = snake.id === selfId;
    const segments = isSelf ? snake.segments.slice(0, -1) : snake.segments;

    if (segments.some((seg) => seg.x === x && seg.y === y)) {
      return true;
    }
  }

  return false;
}

function safeDirections(game, snake, wrapWalls) {
  const head = snake.head();

  return DIRECTIONS.filter((dir) => {
    const cell = nextCell(head, dir, wrapWalls);

    if (!wrapWalls) {
      if (cell.x < 0 || cell.x >= GRID_COLS || cell.y < 0 || cell.y >= GRID_ROWS) {
        return false;
      }
    }

    return !isOccupiedBySnake(game, cell.x, cell.y, snake.id);
  });
}

export function updateBots(game, wrapWalls = true) {
  for (const snake of game.snakes) {
    if (!snake.isBot || !snake.alive) {
      continue;
    }

    const head = snake.head();
    const options = safeDirections(game, snake, wrapWalls);

    if (options.length === 0) {
      continue;
    }

    const food = nearestFood(head, game.foods);
    let choice = options[Math.floor(Math.random() * options.length)];

    if (food) {
      const preferred = directionToward(head, food);
      if (preferred && options.some((dir) => dir.x === preferred.x && dir.y === preferred.y)) {
        choice = preferred;
      }
    }

    snake.setDirection(choice);
  }
}
